def get_settings(db: Session) -> dict:
    s = dict(DEFAULT_SETTINGS)
    for row in db.scalars(select(m.Setting)):
        if row.value is not None:
            s[row.key] = row.value
    return s


def set_setting(db: Session, key: str, value: Optional[str]) -> None:
    row = db.get(m.Setting, key)
    if row is None:
        db.add(m.Setting(key=key, value=value))
    else:
        row.value = value


def product_query(db: Session, q: str = "", form: str = "", status: str = "", imprint: str = "",
                  series_id: Optional[int] = None, contributor_id: Optional[int] = None,
                  missing: str = ""):
    stmt = select(m.Product)
    if q:
        like = f"%{q}%"
        stmt = stmt.where(or_(m.Product.title.ilike(like), m.Product.isbn13.like(f"%{q.replace('-', '')}%"),
                              m.Product.record_reference.ilike(like),
                              m.Product.id.in_(select(m.ProductContributor.product_id).join(m.Contributor).where(
                                  or_(m.Contributor.person_name.ilike(like), m.Contributor.person_name_inverted.ilike(like),
                                      m.Contributor.corporate_name.ilike(like))))))
    if form:
        stmt = stmt.where(m.Product.product_form == form)
    if status:
        stmt = stmt.where(m.Product.publishing_status == status)
    if imprint:
        stmt = stmt.where(m.Product.imprint_name == imprint)
    if series_id:
        stmt = stmt.where(m.Product.id.in_(select(m.ProductSeries.product_id).where(m.ProductSeries.series_id == series_id)))
    if contributor_id:
        stmt = stmt.where(m.Product.id.in_(select(m.ProductContributor.product_id).where(m.ProductContributor.contributor_id == contributor_id)))
    if missing == "cover":
        stmt = stmt.where(~m.Product.id.in_(select(m.SupportingResource.product_id).where(m.SupportingResource.content_type == "01")))
    elif missing == "thema":
        stmt = stmt.where(~m.Product.id.in_(select(m.Subject.product_id).where(m.Subject.scheme == "93")))
    elif missing == "description":
        stmt = stmt.where(~m.Product.id.in_(select(m.TextContent.product_id).where(m.TextContent.text_type.in_(["03", "02"]))))
    elif missing == "price":
        stmt = stmt.where(m.Product.rrp_gbp.is_(None))
    elif missing == "contributor":
        stmt = stmt.where(~m.Product.id.in_(select(m.ProductContributor.product_id)))
    elif missing == "unexported":
        stmt = stmt.where(or_(m.Product.last_exported_at.is_(None), m.Product.last_exported_at < m.Product.updated_at))
    return stmt


def count(db: Session, stmt) -> int:
    return db.scalar(select(func.count()).select_from(stmt.subquery()))


def dashboard_stats(db: Session) -> dict:
    total = db.scalar(select(func.count(m.Product.id)))
    by_status = dict(db.execute(select(m.Product.publishing_status, func.count()).group_by(m.Product.publishing_status)).all())
    by_form = dict(db.execute(select(m.Product.product_form, func.count()).group_by(m.Product.product_form).order_by(func.count().desc())).all())
    gaps = {k: count(db, product_query(db, missing=k)) for k in ("cover", "thema", "description", "price", "contributor", "unexported")}
    recent = db.scalars(select(m.ChangeLog).order_by(m.ChangeLog.id.desc()).limit(12)).all()
    last_export = db.scalar(select(m.ExportRun).order_by(m.ExportRun.id.desc()))
    forthcoming = db.scalars(select(m.Product).where(m.Product.publishing_status == "02").order_by(m.Product.publication_date).limit(10)).all()
    return dict(total=total, by_status=by_status, by_form=by_form, gaps=gaps, recent=recent,
                last_export=last_export, forthcoming=forthcoming,
                contributors=db.scalar(select(func.count(m.Contributor.id))),
                series=db.scalar(select(func.count(m.Series.id))))


def log_change(db: Session, product: m.Product, field: str, old, new, who: str = "web") -> bool:
    o = "" if old is None else str(old)
    n = "" if new is None else str(new)
    if o == n:
        return False
    try:  # numeric equality (148 == 148.000)
        if o != "" and n != "" and Decimal(o) == Decimal(n):
            return False
    except Exception:
        pass
    if who == "web":
        from .auth import current_user
        who = current_user.get()
    db.add(m.ChangeLog(product_id=product.id, field=field, old_value=o, new_value=n, changed_by=who))
    product.updated_at = datetime.utcnow()
    return True


def ensure_supply(db: Session, p: m.Product, settings: dict) -> m.SupplyDetail:
    if p.supply_details:
        return p.supply_details[0]
    name = settings.get("default_supplier") or settings["sender_name"]
    sup = db.scalar(select(m.Supplier).where(m.Supplier.name == name))
    if not sup:
        sup = m.Supplier(name=name, role="01")
        db.add(sup); db.flush()
    sd = m.SupplyDetail(supplier=sup, availability="20", market_regions="WORLD")
    p.supply_details.append(sd)
    return sd


def set_rrp(db: Session, p: m.Product, amount: Optional[Decimal], standard_rated: bool, settings: dict) -> None:
    """Set the home-currency RRP (inc tax) and derive the ex-tax price and tax composite from the
    tax settings (book rate by default, standard rate when the product is marked standard-rated)."""
    cur = settings.get("currency") or "GBP"
    sd = ensure_supply(db, p, settings)
    for pr in [pr for pr in sd.prices if pr.currency == cur]:
        sd.prices.remove(pr)
    p.rrp_gbp = amount
    if amount is None:
        return
    rate = Decimal(settings.get("tax_standard_rate") or "0") if standard_rated else Decimal(settings.get("tax_book_rate") or "0")
    code = "S" if standard_rated else (settings.get("tax_book_code") or "Z")
    inc = amount.quantize(Decimal("0.01"))
    exc = (inc / (1 + rate / 100)).quantize(Decimal("0.01"))
    tax = inc - exc
    sd.prices.append(m.Price(price_type="02", amount=inc, currency=cur, tax_rate_code=code,
                             tax_rate_percent=rate, taxable_amount=exc, tax_amount=tax))
    sd.prices.append(m.Price(price_type="01", amount=exc, currency=cur))


